/**
 * Join plans must be connected unless that is impossible: a pattern that shares no variable with what is already
 * evaluated may only be joined when no remaining pattern is connected. These tests hold the LMDB sketch-based planner
 * (used when the statistics support join estimation) to the same rule as the core join optimizer.
 */
class LmdbConnectedJoinPlanTest {

	@Test
	void sketchPipelineDoesNotSeparateConnectedPatternsByACrossProduct() {
		List<String> order = plan(
				"SELECT * WHERE { ?x <urn:test:pA> ?y . ?y <urn:test:pB> ?z . ?w <urn:test:pD> ?v . }");

		assertThat(order).hasSize(3);
		assertThat(Math.abs(order.indexOf("urn:test:pA") - order.indexOf("urn:test:pB")))
				.as("A and B share ?y and must be adjacent, plan was %s", order)
				.isEqualTo(1);
	}

	@Test
	void sketchPipelineEvaluatesDisconnectedGroupsContiguously() {
		List<String> order = plan("SELECT * WHERE { ?a <urn:test:pA> ?b . ?b <urn:test:pB> ?c . "
				+ "?x <urn:test:pX> ?y . ?y <urn:test:pY> ?z . }");

		assertThat(order).hasSize(4);
		assertThat(Math.abs(order.indexOf("urn:test:pA") - order.indexOf("urn:test:pB")))
				.as("group 1 must be contiguous, plan was %s", order)
				.isEqualTo(1);
		assertThat(Math.abs(order.indexOf("urn:test:pX") - order.indexOf("urn:test:pY")))
				.as("group 2 must be contiguous, plan was %s", order)
				.isEqualTo(1);
	}

	private static List<String> plan(String query) {
		TripleSource tripleSource = new EmptyTripleSource();
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(tripleSource, null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.EXPERIMENTAL);
		TupleExpr tupleExpr = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();

		List<QueryOptimizer> optimizers = new ArrayList<>();
		new LmdbQueryOptimizerPipeline(strategy, tripleSource, new CrossProductIsCheapStatistics()).getOptimizers()
				.forEach(optimizers::add);
		assertThat(optimizers).anyMatch(LmdbSketchJoinOptimizer.class::isInstance);
		for (QueryOptimizer optimizer : optimizers) {
			optimizer.optimize(tupleExpr, null, EmptyBindingSet.getInstance());
		}

		List<String> predicates = new ArrayList<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				predicates.add(node.getPredicateVar().getValue().stringValue());
			}
		});
		return predicates;
	}

	/**
	 * Statistics that make a cross product look cheaper than any connected join, so a planner that does not enforce
	 * connectedness would interleave the patterns of unrelated groups.
	 */
	private static final class CrossProductIsCheapStatistics extends EvaluationStatistics {

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr expr) {
			if (expr instanceof StatementPattern pattern) {
				return switch (pattern.getPredicateVar().getValue().stringValue()) {
				case "urn:test:pA" -> 2;
				case "urn:test:pB" -> 1000;
				case "urn:test:pD" -> 100;
				case "urn:test:pX" -> 3;
				case "urn:test:pY" -> 100;
				default -> 10;
				};
			}
			if (expr instanceof Join join) {
				Set<String> shared = new HashSet<>(join.getLeftArg().getBindingNames());
				shared.retainAll(join.getRightArg().getBindingNames());
				return shared.isEmpty() ? 1 : 1000;
			}
			return super.getCardinality(expr);
		}
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}
	}
}
